import{_ as e}from"./chunks/settings-cal.pc.en.Cdbg9NRR.js";import{_ as o,o as a,c as n,a5 as i}from"./chunks/framework.BjM_ivYE.js";const p=JSON.parse('{"title":"Calibration and tuning","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/troubleshooting/calibration-tuning.md","filePath":"manual/troubleshooting/calibration-tuning.md","lastUpdated":1790646309000}'),r={name:"manual/troubleshooting/calibration-tuning.md"};function s(l,t,h,d,c,g){return a(),n("div",null,[...t[0]||(t[0]=[i('<h1 id="calibration-and-tuning" tabindex="-1">Calibration and tuning <a class="header-anchor" href="#calibration-and-tuning" aria-label="Permalink to &quot;Calibration and tuning&quot;">​</a></h1><p>The calibrations that keep the robot walking steadily are collected under <strong>Robot settings → Calibration</strong> in the app.</p><p><img src="'+e+'" alt="Robot settings → Calibration"></p><h2 id="zmp-calibration" tabindex="-1">ZMP calibration <a class="header-anchor" href="#zmp-calibration" aria-label="Permalink to &quot;ZMP calibration&quot;">​</a></h2><p>ZMP (Zero Moment Point) calibration <strong>finds the center-of-mass offset automatically while the robot stands.</strong> Run it after changing the load, or when the walk drifts to one side.</p><h3 id="before-you-start" tabindex="-1">Before you start <a class="header-anchor" href="#before-you-start" aria-label="Permalink to &quot;Before you start&quot;">​</a></h3><ul><li>Put the robot on <strong>flat, firm ground</strong>.</li><li>Leave <strong>room for the robot to take one step</strong> — it aligns its legs with a step before calibrating.</li><li>The app must be connected to the robot.</li><li><strong>The robot must be standing.</strong> It cannot start while sitting or with control off.</li></ul><h3 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to &quot;Procedure&quot;">​</a></h3><ol><li>Open <strong>Robot settings → Calibration</strong> in the app.</li><li>Under <strong>ZMP Calibration</strong>, press <code>Auto-calibrate ZMP offset</code>. If the robot is not in a state where it can run, the button is locked and <strong>the reason is shown right there</strong> (for example <em>The robot must be standing — ZMP calibration cannot start while sitting or with control off</em>).</li><li>Confirm in the dialog.</li><li>The robot <strong>takes one slow step to square up its legs</strong>, then starts calibrating. The progress window shows <em>Calibrating the ZMP offset…</em> and it takes <strong>up to 60 seconds</strong>.</li><li>On convergence the robot <strong>saves the value itself and returns to STAND.</strong> The window shows <em>ZMP calibration complete.</em> and closes after two seconds.</li><li>Move the robot around and confirm it behaves normally.</li></ol><div class="sb sb-caution"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">CAUTION</p><p><strong>Do not touch the robot</strong> until the calibration finishes. Putting anything on it or pushing it throws the calibration off. Closing the window does not stop it — the robot keeps calibrating.</p></div></div><h3 id="if-it-fails" tabindex="-1">If it fails <a class="header-anchor" href="#if-it-fails" aria-label="Permalink to &quot;If it fails&quot;">​</a></h3><p>A failure <strong>leaves the previous calibration in place.</strong> Act on the reason shown in the window.</p><table tabindex="0"><thead><tr><th>Message on screen</th><th>What to do</th></tr></thead><tbody><tr><td><em>The robot must be standing.</em></td><td>Switch to STAND and run it again</td></tr><tr><td><em>Wait until the robot is completely still, then run it again.</em></td><td>Wait for walking or turning to stop</td></tr><tr><td><em>Place the robot on level ground.</em></td><td>The ground is sloped — move to a flat surface</td></tr><tr><td><em>The alignment step did not finish.</em></td><td>Clear room for one step and run it again</td></tr><tr><td><em>It did not converge within 60 s.</em></td><td>Check that the floor is not soft or slippery, then run it again</td></tr><tr><td><em>The robot is not responding.</em></td><td>Check the <a href="/RBQ/manual/gui/connection.html">connection</a></td></tr></tbody></table><p>The reason is also written to the system log — see <a href="/RBQ/manual/gui/logs.html">Logs</a>.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li>If you changed the load, <strong>update the <a href="/RBQ/manual/troubleshooting/payload_setting.html">payload configuration</a> first</strong>, then calibrate. The other order leaves the calibration tied to the old load.</li><li>The <strong>IMU zero</strong>, <strong>leg home pose (jig)</strong>, <strong>camera</strong> and <strong>docking</strong> calibrations on the same screen are described in <a href="/RBQ/manual/gui/settings.html">Settings</a>.</li></ul><h2 id="still-stuck" tabindex="-1">Still stuck <a class="header-anchor" href="#still-stuck" aria-label="Permalink to &quot;Still stuck {#still-stuck}&quot;">​</a></h2><p>Tell us which calibration failed, the reason shown on screen, and what was loaded on the robot at the time.</p><p><strong>→ <a href="/RBQ/manual/support/">Support</a></strong></p>',19)])])}const m=o(r,[["render",s]]);export{p as __pageData,m as default};
